package com.gomgomapps.math.core;
import java.util.*;import java.io.*;import org.junit.Test;import static org.junit.Assert.*;
public class ContextCalculationMethodsTest {
 @Test public void pendingOldBoxContextRemainsReadableWhileNewQuestionsUseStorage(){Question old=new Question(ContextCalculationMethods.ID,"책 639555권을 상자 21개에 똑같이 나눠 담습니다.\n한 상자에 책을 몇 권씩 담습니까?","poison","0");old.calculationMethod="written";assertEquals(30455,ContextCalculationMethods.read(old).answer());assertTrue(new Checker().check(old,List.of("639555/21=30455"),List.of("30455"),List.of(Checker.StepKind.FULL)).correct());Generator g=new Generator(new Random(268));for(int i=0;i<30;i++)assertFalse(g.next(ContextCalculationMethods.ID,List.of(),false,CurriculumLimits.NONE).prompt.contains("상자"));}
 @Test public void allFourPublicContextsAndWrittenWorkIgnorePoisonedAnswerKeys(){Checker checker=new Checker();for(int op=0;op<4;op++){Question q=ContextCalculationMethods.make(op,6,3);long value=new long[]{9,3,18,2}[op];String expression=new String[]{"6+3","6-3","6*3","6/3"}[op];q.expression="0";q.answers=new String[]{"0"};q.calculationMethod="written";List<String>work=List.of(expression+"="+value);List<Checker.StepKind>kinds=List.of(Checker.StepKind.FULL);assertTrue(checker.checkSteps(q,work,kinds).correct());assertEquals(""+value,WorkAnswer.writtenAnswer(q,work,kinds));assertTrue(checker.check(q,work,List.of(""+value),kinds).correct());assertFalse(checker.check(q,List.of(),List.of(""+(value+1))).correct());HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(3,h.size());assertTrue(h.step(0).accepts("6"));assertTrue(h.step(1).accepts("3"));assertTrue(h.step(2).accepts(""+value));assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}}
 @Test public void methodChoicePersistsWithoutChangingQuestionIdentityAndInactiveWorkIsRetained()throws Exception {Question q=ContextCalculationMethods.make(0,300000,400000);String identity=q.signature();q.calculationMethod="written";assertEquals(identity,q.signature());ByteArrayOutputStream bytes=new ByteArrayOutputStream();new ObjectOutputStream(bytes).writeObject(q);Question copy=(Question)new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray())).readObject();assertEquals("written",copy.calculationMethod);assertEquals(identity,copy.signature());Checker c=new Checker();List<String>draft=new ArrayList<>(List.of("1+1=3"));List<Checker.StepKind>types=List.of(Checker.StepKind.FULL);assertFalse(c.check(copy,draft,List.of("700000"),types).correct());copy.calculationMethod="mental";assertTrue(c.check(copy,draft,List.of("700000"),types).correct());assertEquals(List.of("1+1=3"),draft);assertFalse(c.check(copy,draft,List.of("700001"),types).correct());}
 @Test public void completeSmallSupplyFreshBeforeOldestAndDomainBoundaries(){Set<String>all=new HashSet<>();for(int op=0;op<4;op++)for(int a=0;a<=1;a++)for(int b=0;b<=1;b++){if(op==0&&a+b>1||op==1&&a<b||op==3&&b==0)continue;all.add(ContextCalculationMethods.make(op,a,b).signature());}assertEquals(12,all.size());Generator g=new Generator(new Random(268));CurriculumLimits l=new CurriculumLimits("minGiven=0;maxGiven=1;maxResult=1;nonnegative=true");List<String>history=new ArrayList<>();for(int i=0;i<12;i++){Question q=g.next(ContextCalculationMethods.ID,history,false,l);assertTrue(all.contains(q.signature()));assertFalse(history.contains(q.signature()));history.add(q.signature());}assertEquals(history.get(0),g.next(ContextCalculationMethods.ID,history,false,l).signature());for(int op=0;op<4;op++)assertNotNull(ContextCalculationMethods.read(ContextCalculationMethods.make(op,1000000,op==0?0:1)));for(int[]x:List.of(new int[]{0,1000000,1},new int[]{1,0,1},new int[]{2,1000000,2},new int[]{3,1,0},new int[]{3,7,2})){try{ContextCalculationMethods.make(x[0],x[1],x[2]);fail();}catch(IllegalArgumentException expected){}}}
 @Test public void normalGradeSixFreshAllOperationsAndLargeQuantities(){String pack="na-nied-primary-2024-v1";Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,pack);assertTrue(GlobalCurriculum.pack(p).inGrade(ContextCalculationMethods.ID,6));assertFalse(Curriculum.inCurriculum(Catalog.get(ContextCalculationMethods.ID),2022));Generator g=new Generator(new Random(268));List<String>h=new ArrayList<>();Set<Integer>ops=new HashSet<>();boolean large=false;for(int i=0;i<150;i++){Question q=g.next(ContextCalculationMethods.ID,h,false,GlobalCurriculum.limits(pack,qid(),6));assertFalse(h.contains(q.signature()));h.add(q.signature());var v=ContextCalculationMethods.read(q);ops.add(v.operation());large|=Math.max(v.a(),v.b())>=100000;}assertEquals(Set.of(0,1,2,3),ops);assertTrue(large);}private String qid(){return ContextCalculationMethods.ID;}
}
